{
  "category_edits": [
    {
      "category": "training_strategy",
      "rationale": "Keep Adam and its initial learning rate, then decay the learning rate with a cosine schedule to 10% over the configured epochs, capped at 200. This may improve late-training refinement while preserving batch size, dropout, weight decay, model, loss, seeds, routing and checkpoint selection.",
      "edits": [
        {
          "find": "NUM_EPOCHS    = int(os.environ.get(\"GRU4REC_EPOCHS\", \"200\"))",
          "replace": "NUM_EPOCHS    = min(200, int(os.environ.get(\"GRU4REC_EPOCHS\", \"200\")))"
        },
        {
          "find": "    optimizer = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)\n",
          "replace": "    optimizer = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)\n    scheduler = torch.optim.lr_scheduler.CosineAnnealingLR(\n        optimizer, T_max=max(1, NUM_EPOCHS), eta_min=0.1 * LR\n    )\n"
        },
        {
          "find": "        avg_loss = total_loss / max(NUM_BATCHES, 1)\n",
          "replace": "        scheduler.step()\n        avg_loss = total_loss / max(NUM_BATCHES, 1)\n"
        }
      ]
    }
  ],
  "change_summary": "Add epoch-level cosine learning-rate decay to 10% of the initial rate and enforce the 200-epoch cap. Predictor and model remain unchanged."
}
